import { useState, useCallback, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Wifi, Download, Upload, Activity, Server } from 'lucide-react';
import { ResponsiveContainer, AreaChart, Area, XAxis, Tooltip } from 'recharts';
import './index.css';

function SpeedChecker() {
  const [download, setDownload] = useState(0);
  const [upload, setUpload] = useState(0);
  const [ping, setPing] = useState(0);
  const [testing, setTesting] = useState(false);
  const [history, setHistory] = useState([]);

  const [network, setNetwork] = useState({
    isp: 'Detecting...',
    server: 'Detecting...',
    location: 'Detecting...',
    ip: 'Detecting...',
  });

  const API_BASE = process.env.REACT_APP_API_URL || window.location.origin;

  const loadNetworkInfo = useCallback(async () => {
    try {
      const res = await fetch(`${API_BASE}/api/network-info`, {
        cache: 'no-store',
      });

      const data = await res.json();

      setNetwork({
        isp: data.isp || 'Unknown ISP',
        server: data.server || 'Nearest Server',
        location: data.location || 'Unknown Location',
        ip: data.ip || 'Hidden',
      });
    } catch (error) {
      setNetwork({
        isp: 'Unknown ISP',
        server: 'Nearest Server',
        location: 'Unknown Location',
        ip: 'Hidden',
      });
    }
  }, [API_BASE]);

  useEffect(() => {
    loadNetworkInfo();
  }, [loadNetworkInfo]);

  const runTest = useCallback(async () => {
    try {
      setTesting(true);
      setDownload(0);
      setUpload(0);
      setPing(0);
      setHistory([]);

      await loadNetworkInfo();

      // ================= PING =================
      const pingStart = performance.now();

      await fetch(`${API_BASE}/api/ping?t=${Date.now()}`, {
        cache: 'no-store',
      });

      setPing(Math.round(performance.now() - pingStart));

      // ================= DOWNLOAD =================
      const downloadStart = performance.now();
      let downloadedBytes = 0;

      for (let i = 0; i < 5; i++) {
        const res = await fetch(`${API_BASE}/api/download?size=5242880&t=${Date.now()}-${i}`, {
          cache: 'no-store',
        });

        if (!res.body) {
          throw new Error('Download stream not supported in this browser');
        }

        const reader = res.body.getReader();

        while (true) {
          const { value, done } = await reader.read();

          if (done) break;

          downloadedBytes += value.byteLength;

          const seconds = (performance.now() - downloadStart) / 1000;
          const mbps = (downloadedBytes * 8) / seconds / 1_000_000;
          const rounded = Math.round(mbps);

          setDownload(rounded);

          setHistory((prev) => [
            ...prev.slice(-25),
            {
              time: prev.length + 1,
              speed: rounded,
            },
          ]);
        }
      }

      // ================= UPLOAD =================
      const uploadChunk = new Uint8Array(2 * 1024 * 1024);

      // getRandomValues max limit is 65536 bytes, so fill in chunks
      if (window.crypto?.getRandomValues) {
        for (let i = 0; i < uploadChunk.length; i += 65536) {
          const slice = uploadChunk.subarray(i, i + 65536);
          crypto.getRandomValues(slice);
        }
      }

      let uploadedBytes = 0;
      const uploadStart = performance.now();

      for (let i = 0; i < 8; i++) {
        await fetch(`${API_BASE}/api/upload?t=${Date.now()}-${i}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/octet-stream',
          },
          body: uploadChunk,
          cache: 'no-store',
        });

        uploadedBytes += uploadChunk.byteLength;

        const seconds = (performance.now() - uploadStart) / 1000;
        const mbps = (uploadedBytes * 8) / seconds / 1_000_000;

        setUpload(Math.round(mbps));
      }
    } catch (err) {
      console.error(err);
      alert(err.message || 'Speed test failed');
    } finally {
      setTesting(false);
    }
  }, [API_BASE, loadNetworkInfo]);

  return (
    <div className="speed-page">
      <div className="speed-app">
        <header className="topbar">
          <h1 className="logo-text">⚡ SpeedChecker</h1>

          <button className="run-btn" onClick={runTest} disabled={testing}>
            {testing ? 'Testing...' : 'Start Test'}
          </button>
        </header>

        <main>
          <section className="hero-section">
            <div className="speed-value">{download.toFixed(1)}</div>
            <div className="speed-unit">Mbps</div>

            <div className={`neon-ring ${testing ? 'ring-active' : ''}`}>
              <div className="ring-inner">
                <Wifi size={34} />
                <span>{testing ? 'Running' : 'Ready'}</span>
              </div>
            </div>

            <p className="status-text">
              {testing ? 'Testing your internet speed...' : 'Click start to test your connection'}
            </p>
          </section>

          <section className="cards">
            <div className="card">
              <Download size={22} />
              <p>Download</p>
              <h3>{download} Mbps</h3>
            </div>

            <div className="card">
              <Upload size={22} />
              <p>Upload</p>
              <h3>{upload} Mbps</h3>
            </div>

            <div className="card">
              <Activity size={22} />
              <p>Ping</p>
              <h3>{ping} ms</h3>
            </div>

            <div className="card">
              <Server size={22} />
              <p>Status</p>
              <h3>{testing ? 'Running' : 'Stable'}</h3>
            </div>
          </section>

          <section className="graph-box">
            <h2>Live Speed Graph</h2>

            <ResponsiveContainer width="100%" height={250}>
              <AreaChart data={history}>
                <XAxis dataKey="time" hide />
                <Tooltip
                  contentStyle={{
                    background: '#050816',
                    border: '1px solid #00f7ff',
                    borderRadius: '12px',
                    color: '#fff',
                  }}
                />
                <Area
                  type="monotone"
                  dataKey="speed"
                  stroke="#00f7ff"
                  fill="rgba(0,247,255,0.2)"
                  strokeWidth={3}
                />
              </AreaChart>
            </ResponsiveContainer>
          </section>

          <section className="network-box">
            <h2>Network Details</h2>

            <div className="network-grid">
              <div>
                <span>ISP</span>
                <strong>{network.isp}</strong>
              </div>

              <div>
                <span>Server</span>
                <strong>{network.server}</strong>
              </div>

              <div>
                <span>Location</span>
                <strong>{network.location}</strong>
              </div>

              <div>
                <span>IP Address</span>
                <strong>{network.ip}</strong>
              </div>
            </div>
          </section>

          <section className="seo-box">
            <h2>How Fast Is Your Internet?</h2>
            <p>
              Test your download speed, upload speed, ping and network stability instantly with
              SpeedChecker.
            </p>
          </section>
        </main>

        <footer className="footer">
          <Link to="/privacy-policy">Privacy</Link>
          <Link to="/terms-of-service">Terms</Link>
          <Link to="/about-us">About</Link>
        </footer>
      </div>
    </div>
  );
}

export default SpeedChecker;
